// Turn the build's generated wrangler config into one that deploys THIS worker.
//
// `vinext build` emits dist/server/wrangler.json naming the worker "sites-project"
// with no routes at all. It also keeps the SSR entrypoint generated by the
// Cloudflare Vite plugin, even when Next is configured for static export. This
// site has no same-origin API or request-specific rendering, so publishing that
// entrypoint only makes every HTML/404 request pay Worker CPU. This script turns
// the generated config into an asset-only deployment for the real Worker.
//
// The assertions fail closed on purpose. wrangler's account-level route call
// deletes routes not present in the config, so an empty or partial routes array
// would take the site off the air with no error anywhere.
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'

const SRC = 'dist/server/wrangler.json'
const OUT = 'dist/server/wrangler.deploy.json'
const PRERENDER = 'dist/server/vinext-prerender.json'
const WORKER = 'leaddrive-site'
const ZONE = 'leaddrivecrm.org'

const ROUTES = [
  { pattern: `${ZONE}/*`, zone_name: ZONE },
  { pattern: `www.${ZONE}/*`, zone_name: ZONE },
  // Only this one is a custom domain. On the apex or www Cloudflare answers
  // 100117 "Hostname already has externally managed DNS records".
  { pattern: `new.${ZONE}`, custom_domain: true },
]

const config = JSON.parse(readFileSync(SRC, 'utf8'))
const prerender = JSON.parse(readFileSync(PRERENDER, 'utf8'))
config.name = WORKER
config.topLevelName = WORKER
config.workers_dev = false
config.routes = ROUTES
config.assets.not_found_handling = '404-page'
config.assets.html_handling = 'auto-trailing-slash'

// With no Worker entrypoint, every request is handled by Static Assets:
// existing pages are served directly and misses use the generated 404.html.
// Remove the binding too; it only exists for Worker code to call env.ASSETS.
delete config.main
delete config.assets.binding
delete config.assets.run_worker_first

const assetRoot = resolve(dirname(SRC), config.assets.directory)
const routeAssetExists = (route) =>
  existsSync(resolve(assetRoot, `${route}.html`)) ||
  existsSync(resolve(assetRoot, route, 'index.html'))

const headersPath = resolve(assetRoot, '_headers')
const parseHeaderRules = (source) => {
  const rules = new Map()
  let currentRule

  for (const line of source.split(/\r?\n/)) {
    const trimmed = line.trim()
    if (!trimmed || trimmed.startsWith('#')) continue

    if (!/^\s/.test(line)) {
      currentRule = trimmed
      if (!rules.has(currentRule)) rules.set(currentRule, new Map())
      continue
    }

    const separator = trimmed.indexOf(':')
    if (!currentRule || separator < 1) continue
    const name = trimmed.slice(0, separator).toLowerCase()
    const value = trimmed.slice(separator + 1).trim()
    rules.get(currentRule).set(name, value)
  }

  return rules
}

const problems = []
if (config.name !== WORKER) problems.push(`name is ${config.name}`)
if (config.workers_dev !== false) problems.push('workers_dev is not false')
if (!Array.isArray(config.routes) || config.routes.length !== 3) {
  problems.push(`expected 3 routes, got ${config.routes?.length}`)
}
if (!config.assets?.directory) problems.push('assets.directory is missing — every static file would be dropped')
if (config.main) problems.push('main is still present — HTML would invoke the SSR Worker')
if (config.assets?.binding) problems.push('assets.binding is still present without a Worker entrypoint')
if (config.assets?.run_worker_first !== undefined) problems.push('assets.run_worker_first is present — assets must never invoke a Worker')
if (config.assets?.not_found_handling !== '404-page') problems.push('assets.not_found_handling is not 404-page')
if (config.assets?.html_handling !== 'auto-trailing-slash') problems.push('assets.html_handling is not auto-trailing-slash')
if (prerender.trailingSlash !== false) problems.push('prerender manifest must keep trailingSlash=false')
if (!Array.isArray(prerender.routes) || prerender.routes.length === 0) {
  problems.push('prerender manifest has no routes')
} else {
  const incompleteRoutes = prerender.routes.filter((route) => route.status !== 'rendered')
  if (incompleteRoutes.length) {
    const details = incompleteRoutes
      .map((route) => `${route.path ?? route.route}: ${route.status}${route.reason ? ` (${route.reason})` : ''}`)
      .join(', ')
    problems.push(`prerender did not render every route: ${details}`)
  }
}
if (!existsSync(resolve(assetRoot, 'index.html'))) problems.push('static home page is missing')
if (!existsSync(resolve(assetRoot, '404.html'))) problems.push('static 404 page is missing')
if (!existsSync(resolve(assetRoot, '_redirects'))) problems.push('static redirect rules are missing')
if (!existsSync(headersPath)) {
  problems.push('static security headers are missing')
} else {
  const headerRules = parseHeaderRules(readFileSync(headersPath, 'utf8'))
  const globalHeaders = headerRules.get('/*')
  for (const header of [
    'content-security-policy',
    'permissions-policy',
    'referrer-policy',
    'strict-transport-security',
    'x-content-type-options',
    'x-frame-options',
  ]) {
    if (!globalHeaders?.has(header)) problems.push(`static global header ${header} is missing`)
  }

  const assetCache = headerRules.get('/_next/static/*')?.get('cache-control')?.toLowerCase()
  if (assetCache !== 'public, max-age=31536000, immutable') {
    problems.push('fingerprinted static assets are not configured for immutable one-year browser caching')
  }
}
if (!existsSync(resolve(assetRoot, 'build-stamp.json'))) problems.push('build stamp is missing')
for (const route of ['ru', 'en', 'privacy', 'terms-of-use', 'solutions/sales-crm']) {
  if (!routeAssetExists(route)) problems.push(`static route /${route} is missing`)
}
if (problems.length) {
  console.error(`cf-deploy-config: refusing to write ${OUT}\n  ${problems.join('\n  ')}`)
  process.exit(1)
}

writeFileSync(OUT, JSON.stringify(config, null, 2))
console.log(`cf-deploy-config: ${OUT} -> ${config.name}, asset-only, ${config.routes.length} triggers`)
